import { useEffect, useState } from 'react';
import { Moon, Sun } from 'lucide-react';

export function applyTheme(value: 'light' | 'dark') {
  document.documentElement.dataset.theme = value;
  document.documentElement.style.colorScheme = value;
  window.dispatchEvent(new CustomEvent('calv-theme-change', { detail: value }));
}

export function initializeTheme() {
  let dark = false;
  try { dark = localStorage.getItem('calv-theme') === 'dark'; } catch { /* Use light mode. */ }
  applyTheme(dark ? 'dark' : 'light');
}

export function ThemeToggle() {
  const [theme, setTheme] = useState(document.documentElement.dataset.theme || 'light');
  useEffect(() => {
    const sync = () => setTheme(document.documentElement.dataset.theme || 'light');
    sync();
    window.addEventListener('calv-theme-change', sync);
    return () => window.removeEventListener('calv-theme-change', sync);
  }, []);
  function changeTheme(value: 'light' | 'dark') {
    applyTheme(value);
    setTheme(value);
    try { localStorage.setItem('calv-theme', value); } catch { /* Preference is optional. */ }
  }
  return (
    <div className="theme-toggle" role="group" aria-label="Appearance / Aparência">
      <button type="button" onClick={() => changeTheme('light')} aria-label="Modo claro / Light mode" aria-pressed={theme === 'light'} title="Modo claro / Light mode"><Sun size={16} strokeWidth={1.5} /></button>
      <button type="button" onClick={() => changeTheme('dark')} aria-label="Modo escuro / Dark mode" aria-pressed={theme === 'dark'} title="Modo escuro / Dark mode"><Moon size={16} strokeWidth={1.5} /></button>
    </div>
  );
}
