import { useState } from 'react';
import { NavBar } from '../components/navBar';
import { Footer } from '../components/footer';
import { Link } from 'react-router-dom';

export function ContactSuccess() {
  const [language, setLanguage] = useState<'en' | 'pt'>(() => {
    try { return localStorage.getItem('contact-language') === 'pt' ? 'pt' : 'en'; } catch { return 'en'; }
  });
  function changeLanguage(value: 'en' | 'pt') {
    setLanguage(value);
    try { localStorage.setItem('contact-language', value); } catch { /* Preference is optional. */ }
  }
  const pt = language === 'pt';
  return (
    <div className="relative min-h-screen flex flex-col bg-white text-black" lang={language}>
      <NavBar language={language} onLanguageChange={changeLanguage} />
    <main className="min-h-[75vh] flex-1 w-full flex flex-col items-center justify-center pt-24 pb-12">
      <div className="relative w-full max-w-5xl">
      <p className="absolute top-0 left-1/2 -translate-x-1/2 z-10 text-sm text-center w-max max-w-full">{pt ? 'OBRIGADA' : 'THANK YOU'}</p>
      <h1 className="w-full container mx-auto max-w-5xl lg:px-0 px-[8vw] flex flex-col text-[3rem] sm:text-[4rem] lg:text-[7rem] font-normal leading-[1.15]" aria-label={pt ? 'Formulário enviado com sucesso' : 'Form submitted successfully'}>
        <span className="self-start">{pt ? 'FORMULÁRIO' : 'FORM'}</span>
        <span className="self-end">{pt ? 'ENVIADO' : 'SUBMITTED'}</span>
        <span className="self-center text-center relative">{pt ? 'COM SUCESSO' : 'SUCCESSFULLY'}<span className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-10 text-[.65rem] leading-normal whitespace-nowrap">{pt ? 'ENTRAREI EM CONTACTO EM BREVE' : 'I’LL BE IN TOUCH SOON'}</span></span>
      </h1>
      <div className="flex justify-center mt-8">
        <Link to="/" className="border border-black px-6 py-3 text-xs hover:bg-black hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-black">
          {pt ? 'VOLTAR AO INÍCIO' : 'BACK TO HOME'} ↗
        </Link>
      </div>
      </div>
    </main>
    <Footer />
    </div>
  );
}
