import { useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import './siteCursor.css';

export function SiteCursor() {
  const { pathname } = useLocation();
  const dot = useRef<HTMLDivElement>(null);
  const ring = useRef<HTMLDivElement>(null);
  const enabled = /^\/(contacts?(\/|$)|projects(-|\/|$))/.test(pathname);

  useEffect(() => {
    if (!enabled) return;
    const media = window.matchMedia('(hover: hover) and (pointer: fine)');
    let dispose = () => {};
    function setup() {
      dispose();
      if (!media.matches) return;
      document.documentElement.classList.add('site-cursor-active');
      let frame = 0;
      let x = 0, y = 0, ringX = 0, ringY = 0;
      let visible = false;
      let hovering = false;
      const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      function render() {
        const smoothing = reducedMotion ? 1 : 0.18;
        ringX += (x - ringX) * smoothing;
        ringY += (y - ringY) * smoothing;
        if (dot.current && ring.current) {
          dot.current.style.transform = `translate3d(${x}px, ${y}px, 0) translate(-50%, -50%)`;
          ring.current.style.transform = `translate3d(${ringX}px, ${ringY}px, 0) translate(-50%, -50%) scale(${hovering ? 1.5 : 1})`;
        }
        if (Math.abs(x - ringX) + Math.abs(y - ringY) > 0.1) frame = requestAnimationFrame(render);
        else frame = 0;
      }
      function hide() {
        visible = false;
        dot.current?.classList.remove('is-visible');
        ring.current?.classList.remove('is-visible');
        cancelAnimationFrame(frame);
        frame = 0;
      }
      function move(event: PointerEvent) {
        if (event.pointerType === 'touch') { hide(); return; }
        x = event.clientX;
        y = event.clientY;
        hovering = event.target instanceof Element && !!event.target.closest('a, button, input, select, textarea, label, [role="button"]');
        if (!visible) {
          ringX = x; ringY = y; visible = true;
          dot.current?.classList.add('is-visible');
          ring.current?.classList.add('is-visible');
        }
        if (!frame) frame = requestAnimationFrame(render);
      }
      window.addEventListener('pointermove', move);
      document.documentElement.addEventListener('pointerleave', hide);
      window.addEventListener('blur', hide);
      dispose = () => {
        hide();
        document.documentElement.classList.remove('site-cursor-active');
        window.removeEventListener('pointermove', move);
        document.documentElement.removeEventListener('pointerleave', hide);
        window.removeEventListener('blur', hide);
      };
    }
    setup();
    media.addEventListener('change', setup);
    return () => { dispose(); media.removeEventListener('change', setup); };
  }, [enabled, pathname]);

  return enabled ? <div className="site-cursor" aria-hidden="true"><div ref={dot} className="site-cursor-dot" /><div ref={ring} className="site-cursor-ring" /></div> : null;
}
