import { useEffect, useState } from 'react';
type Language = 'en' | 'pt';
function readLanguage(): Language {
  try { return localStorage.getItem('contact-language') === 'pt' ? 'pt' : 'en'; } catch { return 'en'; }
}
export function useLanguage(): [Language, (value: Language) => void] {
  const [language, setLanguage] = useState<Language>(readLanguage);
  useEffect(() => {
    const sync = (event: Event) => setLanguage((event as CustomEvent<Language>).detail);
    window.addEventListener('calv-language', sync);
    return () => window.removeEventListener('calv-language', sync);
  }, []);
  function changeLanguage(value: Language) {
    setLanguage(value);
    try { localStorage.setItem('contact-language', value); } catch { /* Preference is optional. */ }
    window.dispatchEvent(new CustomEvent('calv-language', { detail: value }));
  }
  return [language, changeLanguage];
}
