import { useEffect, useState } from "react";
import { IsProjectsRoute } from "../functions/isProject";
import { Link } from "react-router-dom";

import { ThemeToggle } from "./themeToggle";

import { useLanguage } from "../hooks/useLanguage";

type NavBarProps = {
    language?: 'en' | 'pt';
    onLanguageChange?: (language: 'en' | 'pt') => void;
};

export function NavBar({ language, onLanguageChange }: NavBarProps = {}) {

    const [savedLanguage, changeSavedLanguage] = useLanguage();
    const activeLanguage = language || savedLanguage;
    const changeLanguage = onLanguageChange || changeSavedLanguage;
    const [currentDate, setCurrentDate] = useState<string>('');

    useEffect(() => {
      const intervalId = setInterval(() => {
        const date = new Date();
        const options: Intl.DateTimeFormatOptions = {
          weekday: 'long',
          year: 'numeric',
          month: 'long',
          day: 'numeric',
          hour: 'numeric',
          minute: 'numeric',
          second: 'numeric',
        };
        const formattedDate = new Intl.DateTimeFormat('en-US', options).format(date);
        setCurrentDate(formattedDate);
      }, 1000);
  
      return () => clearInterval(intervalId);
    }, []);

    return (
        <nav className={`site-nav h-16 px-6 py-4 flex gap-3 items-center justify-between absolute top-0 left-0 w-full overflow-hidden ${IsProjectsRoute() ? "bg-black" : " bg-white"}`}>
            <div className={`flex gap-3 sm:gap-5 text-xs ${IsProjectsRoute() ? "text-white" : " text-black"}`}>
                <Link to={`/`}>About</Link>
                <Link to={`/projects-grid`}>Projects</Link>
                <Link to="/contacts">Contacts</Link>
            </div>
            {<div className={`flex gap-2 items-center text-xs ${IsProjectsRoute() ? 'text-white' : 'text-black'}`} role="group" aria-label="Language / Idioma">
                <button type="button" aria-pressed={activeLanguage === 'en'} className={activeLanguage === 'en' ? 'underline underline-offset-4' : 'opacity-50'} onClick={() => changeLanguage('en')}>EN</button>
                <span aria-hidden="true">/</span>
                <button type="button" aria-pressed={activeLanguage === 'pt'} className={activeLanguage === 'pt' ? 'underline underline-offset-4' : 'opacity-50'} onClick={() => changeLanguage('pt')}>PT</button>
            </div>}
            <div className="flex items-center gap-5 ml-auto">
                <div className={IsProjectsRoute() ? "text-white" : "text-black"}><ThemeToggle /></div>
                <p className={`hidden lg:flex text-xs ${IsProjectsRoute() ? "text-white" : " text-black"}`}>{currentDate}</p>
            </div>
        </nav>
    );
}

