import { FormEvent, useState } from 'react';
import { NavBar } from '../components/navBar';
import { Footer } from '../components/footer';
import './Contact.css';
import { consts } from '../data/consts';

const services = ['Branding', 'Visual identity', 'Editorial', 'Social media', 'Packaging', 'Graphic design', 'Other'];

const portuguese: Record<string, string> = {
  "LET’S WORK": "VAMOS",
  "TOGETHER.": "TRABALHAR JUNTOS",
  "HAVE AN IDEA IN MIND? TELL ME ABOUT YOUR PROJECT, WHAT YOU NEED AND WHEN YOU NEED IT. LET’S MAKE SOMETHING CRAZY!": "TENS UMA IDEIA EM MENTE? CONTA-ME SOBRE O TEU PROJETO, O QUE PRECISAS E PARA QUANDO. VAMOS CRIAR ALGO INCRÍVEL!",
  "PREFER TO SAY HELLO DIRECTLY?": "PREFERES FALAR DIRETAMENTE?",
  "LISBON, PORTUGAL": "LISBOA, PORTUGAL",
  "OPEN TO PROJECTS EVERYWHERE": "DISPONÍVEL PARA PROJETOS EM TODO O MUNDO",
  "01 / GENERAL INFORMATION": "01 / INFORMAÇÕES GERAIS",
  "02 / YOUR PROJECT": "02 / O TEU PROJETO",
  "First name": "Nome",
  "Last name": "Apelido",
  "Brand / company": "Marca / empresa",
  "Phone number": "Número de telemóvel",
  "Estimated budget": "Investimento estimado",
  "Select an option": "Seleciona uma opção",
  "Under €500": "Menos de 500 €",
  "Let’s discuss": "A definir em conjunto",
  "Preferred timeline": "Para quando precisas",
  "Within a month": "Dentro de um mês",
  "2–3 months": "2–3 meses",
  "3–6 months": "3–6 meses",
  "Flexible": "Flexível",
  "Tell me about your project": "Fala-me sobre o teu projeto",
  "What do you need?": "Que serviço procuras?",
  "Please select at least one service.": "Seleciona pelo menos um serviço.",
  "Anything else you’d like to share?": "Há mais alguma coisa que queiras partilhar?",
  "* Required fields. Your enquiry is sent via FormSubmit to Carlota’s email.": "* Campos obrigatórios. O teu pedido é enviado através do FormSubmit para o email da Carlota.",
  "SEND ENQUIRY": "ENVIAR PEDIDO",
  "Branding": "Branding",
  "Visual identity": "Identidade visual",
  "Editorial": "Editorial",
  "Social media": "Redes sociais",
  "Packaging": "Packaging",
  "Graphic design": "Design gráfico",
  "Other": "Outro"
};

export function Contact() {
  const [language, setLanguage] = useState<'en' | 'pt'>(() => {
    try { return localStorage.getItem('contact-language') === 'pt' ? 'pt' : 'en'; } catch { return 'en'; }
  });
  const t = (text: string) => language === 'pt' ? portuguese[text] || text : text;
  function changeLanguage(value: 'en' | 'pt') {
    setLanguage(value);
    try { localStorage.setItem('contact-language', value); } catch { /* Preference is optional. */ }
  }

  const returnUrl = new URL(`${consts.baseRoute}/contacts/success`, window.location.origin);
  const [selected, setSelected] = useState<string[]>([]);
  const [serviceError, setServiceError] = useState(false);

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    if (!selected.length) {
      event.preventDefault();
      setServiceError(true);
    }
  }

  return (
    <div className="contact-page" lang={language}>
      <NavBar language={language} onLanguageChange={changeLanguage} />
      <main className="contact-main">
        <header className="contact-heading">
          <h1 id="contact-title">{t("LET’S WORK")}<br /><span>{language === 'pt' ? <>TRABALHAR<br />JUNTOS</> : t("TOGETHER.")}</span></h1>
          <p>{t("HAVE AN IDEA IN MIND? TELL ME ABOUT YOUR PROJECT, WHAT YOU NEED AND WHEN YOU NEED IT. LET’S MAKE SOMETHING CRAZY!")}</p>
        </header>
        <aside className="contact-direct">
          <p>{t("PREFER TO SAY HELLO DIRECTLY?")}</p>
          <a href="mailto:carlottalves@gmail.com">carlottalves@gmail.com ↗</a>
          <p className="contact-location">{t("LISBON, PORTUGAL")}<br />{t("OPEN TO PROJECTS EVERYWHERE")}</p>
        </aside>
        <section className="contact-content" aria-labelledby="contact-title">
          <form id="contact-form" className="contact-form" action="https://formsubmit.co/carlottalves@gmail.com" method="POST" onSubmit={handleSubmit}>
            <input type="hidden" name="_next" value={returnUrl.href} />
            <input type="hidden" name="_subject" value="Novo pedido de projeto — Calv_Heetos" />
            <input type="hidden" name="_template" value="table" />
            <input type="text" name="_honey" tabIndex={-1} autoComplete="off" aria-hidden="true" style={{ display: 'none' }} />
            <p className="contact-section-label">{t("01 / GENERAL INFORMATION")}</p>
            <div className="contact-fields">
              <label>{t("First name")} <span>*</span><input name="name" autoComplete="given-name" required maxLength={80} /></label>
              <label>{t("Last name")} <span>*</span><input name="surname" autoComplete="family-name" required maxLength={80} /></label>
              <label>Email <span>*</span><input name="email" type="email" autoComplete="email" required maxLength={200} /></label>
              <label>{t("Brand / company")}<input name="company" autoComplete="organization" maxLength={150} /></label>
              <label>{t("Phone number")}<input name="phone" type="tel" autoComplete="tel" maxLength={40} /></label>
              <label>{t("Estimated budget")}<select name="budget" defaultValue=""><option value="">{t("Select an option")}</option><option value="Under €500">{t("Under €500")}</option><option>500–1.500 €</option><option>1.500–3.000 €</option><option>€3,000+</option><option value="Let’s discuss">{t("Let’s discuss")}</option></select></label>
            </div>
            <p className="contact-section-label">{t("02 / YOUR PROJECT")}</p>
            <label>{t("Preferred timeline")}<select name="timeline" defaultValue=""><option value="">{t("Select an option")}</option><option value="Within a month">{t("Within a month")}</option><option value="2–3 months">{t("2–3 months")}</option><option value="3–6 months">{t("3–6 months")}</option><option value="Flexible">{t("Flexible")}</option></select></label>
            <label>{t("Tell me about your project")} <span>*</span><textarea name="message" rows={2} required maxLength={2000} /></label>
            <fieldset className="contact-services" aria-describedby={serviceError ? 'service-error' : undefined}>
              <legend>{t("What do you need?")} <span>*</span></legend>
              <div className="contact-options">{services.map(service => (
                <label key={service} className="contact-option">
                  <input type="checkbox" name="services" value={service} checked={selected.includes(service)} onChange={event => {
                    setSelected(previous => event.target.checked ? [...previous, service] : previous.filter(value => value !== service));
                    setServiceError(false);
                  }} /><span>{t(service)}</span>
                </label>
              ))}</div>
              {serviceError && <p id="service-error" role="alert">{t("Please select at least one service.")}</p>}
            </fieldset>
            <label>{t("Anything else you’d like to share?")}<textarea name="extra" rows={2} maxLength={800} /></label>
            <p className="contact-note">{t("* Required fields. Your enquiry is sent via FormSubmit to Carlota’s email.")}</p>
            <button type="submit" className="contact-submit">{t("SEND ENQUIRY")} <span aria-hidden="true">→</span></button>
          </form>
        </section>
      </main>
      <Footer />
    </div>
  );
}
