import cursor from '../assets/cursor.png'
import { Footer } from '../components/footer';
import { NavBar } from '../components/navBar';
import { useLanguage } from '../hooks/useLanguage';
export function Home() {
  const [language, changeLanguage] = useLanguage();
  const pt = language === 'pt';
  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const cursor = document.getElementById('custom-cursor');
    if (cursor) {
      const x = e.clientX;
      const y = e.clientY;
      cursor.style.left = `${x}px`;
      cursor.style.top = `${y}px`;
    }
  };
  return (
    <div onMouseMove={handleMouseMove} className='relative w-full min-h-screen h-full cursor-none flex flex-col justify-between'>
      <NavBar language={language} onLanguageChange={changeLanguage} />
      <div
        id="custom-cursor"
        style={{
          position: 'absolute',
          width: '40px',
          height: '40px',
          backgroundImage: `url(${cursor})`,
          backgroundSize: 'cover',
          pointerEvents: 'none',
          zIndex: "999"
        }}
      />
      <div className='absolute bottom-32 sm:bottom-auto top-auto sm:top-16 left-4 sm:left-1/2 sm:-translate-1/2'>
        <p className='sm:max-w-[35rem] max-w-full text-[.55rem] sm:text-[.65rem] uppercase'>
          {pt ? 'Olá! Sou a Carlota Alves, designer gráfica em Lisboa, Portugal. Especializo-me em branding, identidade, redes sociais e comunicação visual. Através dos meus estudos na ESAD e da minha experiência, desenvolvi uma paixão por criar designs inovadores e com significado. Seja na criação de logótipos, produção gráfica ou design digital, estou aqui para dar vida às tuas ideias. Explora os meus projetos e vamos colaborar para criar algo incrível!' : 'Hey there! I’m Carlota Alves, a graphic designer based in Lisbon, Portugal. I’m specialized in branding, identity design, social media and visual communication. I’ve developed a strong passion for creating innovative and meaningful designs through my studies at ESAD and my experience. Whether it’s logo creation, print production, or digital design, I’m here to help bring your ideas to life. Feel free to check out some of my work and let’s collaborate to create something\xa0crazy!'}
        </p>
      </div>
      <div className="pt-28 w-full h-full min-h-[50vh] container mx-auto max-w-5xl lg:px-0 px-[8vw] flex justify-center items-center flex-col">
        <div className='w-full flex justify-start'>
          <p className='text-[3rem] sm:text-[4rem] lg:text-[7rem]'>{pt ? 'OLÁ, SOU A' : "HELLO, I'M"}</p>
        </div>
        <div className='flex items-end w-full flex-col lg:leading-[7rem] leading-[5rem]'>
          <p className='text-[3rem] sm:text-[4rem] lg:text-[7rem]'>CARLOTA</p>
          <p className='sm:tracking-[5px] tracking-[2px] text-sm lg:text-md lg:tracking-[14px]'>{pt ? 'SOU A DESIGNER' : "I'M JUST THE DESIGNER"}</p>
        </div>
        <div className='flex justify-center text-center'>
          <p className='text-[3rem] sm:text-[4rem] lg:text-[7rem]'>ALVES</p>
        </div>
      </div>
      <Footer />
    </div>
  );
}

