import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import './theme.css';
import { initializeTheme } from './components/themeToggle';
import reportWebVitals from './reportWebVitals';
import { Home } from './pages/Home';
import { BrowserRouter, Route, Routes } from 'react-router-dom';
import { Projects } from './pages/Projects';
import ProjectsGrid from './pages/ProjectsGrid';
import { consts } from './data/consts';
import ProjectPage from './pages/ProjectPage/page';
import { Contact } from './pages/Contact';
import { ContactSuccess } from './pages/ContactSuccess';
import { SiteCursor } from './components/siteCursor';

const ProjectMap = React.lazy(() => import('./pages/ProjectMap/ProjectMap').then(module => ({ default: module.ProjectMap })));

initializeTheme();

const root = ReactDOM.createRoot(
  document.getElementById('root') as HTMLElement
);
root.render(
  <React.StrictMode>
    <BrowserRouter basename={consts.baseRoute}> 
      <SiteCursor />
      <React.Suspense fallback={<div role="status">A carregar…</div>}>
      <Routes>
        <Route path="/contacts/success" element={<ContactSuccess />} />
        <Route path="/contacts" element={<Contact />} />
        <Route path="/contact" element={<Contact />} />
        <Route path="/*" element={<Home />} /> 
        <Route path="/projects-list" element={<Projects />} /> 
        <Route path="/projects-grid" element={<ProjectsGrid />} /> 
        <Route path="/projects/map" element={<ProjectMap />} /> 
        <Route path="/projects/:id" element={<ProjectPage />} /> 
      </Routes>
      </React.Suspense>
    </BrowserRouter>
  </React.StrictMode>
);

reportWebVitals();

