import { useState } from 'react';
import { consts } from '../data/consts';
import './rootkeyIcons.css';

export function RootkeyIcons({ language }: { language: 'en' | 'pt' }) {
  const [paused, setPaused] = useState(false);
  const asset = (name: string) => `${consts.baseRoute}/projects/19_ROOTKEY_REBRANDING/${name}.svg`;
  return (
    <section className={`rootkey-motion ${paused ? 'is-paused' : ''}`} aria-label={language === 'pt' ? 'Animação das três variantes do símbolo ROOTKey' : 'Animation of the three ROOTKey symbol variants'}>
      <div className="rootkey-icon-grid">
        <div className="rootkey-icon-panel">
          <div className="rk-piece rk-first-left"><img src={asset('icon-left')} alt="" /></div>
          <div className="rk-piece rk-first-middle"><img src={asset('icon-middle')} alt="" /></div>
          <div className="rk-piece rk-first-arrow"><img src={asset('chevron')} alt="" /></div>
          <p>Icon_1<span>ROOTKey</span></p>
        </div>
        <div className="rootkey-icon-panel">
          <div className="rk-piece rk-second-left"><img src={asset('icon-two')} alt="" /></div>
          <div className="rk-piece rk-second-arrow"><img src={asset('chevron')} alt="" /></div>
          <p>Icon_2<span>ROOTKey</span></p>
        </div>
        <div className="rootkey-icon-panel">
          <div className="rk-piece rk-third-arrow"><img src={asset('icon-three')} alt="" /></div>
          <p>Icon_3<span>ROOTKey</span></p>
        </div>
      </div>
      <button type="button" onClick={() => setPaused(value => !value)} aria-pressed={paused}>{language === 'pt' ? (paused ? 'Reproduzir animação' : 'Pausar animação') : (paused ? 'Play animation' : 'Pause animation')}</button>
    </section>
  );
}
