import { useEffect, useState } from "react"
import { Project, projectsData } from '../../data/projects';
import { useParams } from "react-router-dom";
import { NavBar } from "../../components/navBar";
import { applyTheme, initializeTheme } from "../../components/themeToggle";
import { RootkeyIcons } from "../../components/rootkeyIcons";
import ImageCarousel from "../../components/carousel-autoplay";

import { rootkeyRebrand } from "../../data/rootkeyRebrand";

import { useLanguage } from "../../hooks/useLanguage";

const portfolioProjects = [rootkeyRebrand, ...projectsData];

export default function ProjectDetail() {
    const { id } = useParams<{ id: string }>();
    const [language, setLanguage] = useLanguage();
    const [loading, setLoading] = useState(true);
    const [project, setProject] = useState<Project | null>(null);

    useEffect(() => {
        const foundProject = portfolioProjects.find(p => p.id === id || p.href === `/projects/${id}`);
        if (foundProject) {
            setProject(foundProject as Project);
        }
        setLoading(false);
    }, [id]);

    useEffect(() => {
        if (project?.id !== rootkeyRebrand.id) return;
        applyTheme('dark');
        return () => initializeTheme();
    }, [project?.id]);

    const prevProject = () => {
        if (!project) return;
        const currentIndex = portfolioProjects.findIndex(p => p.id === project.id);
        const prevIndex = (currentIndex - 1 + portfolioProjects.length) % portfolioProjects.length;
        setProject(portfolioProjects[prevIndex]);
    };

    const nextProject = () => {
        if (!project) return;
        const currentIndex = portfolioProjects.findIndex(p => p.id === project.id);
        const nextIndex = (currentIndex + 1) % portfolioProjects.length;
        setProject(portfolioProjects[nextIndex]);
    };

    if (loading || !project) {
        return <div>Loading...</div>
    }

    return (
        <div className="relative flex flex-col w-full h-full pt-16 pb-8 md:flex-row">
            <NavBar language={language} onLanguageChange={setLanguage} />
            <div className="flex flex-col w-full h-full md:flex-row">
                {/* Left side - Image */}
                <div className="w-full md:w-1/2">
                    {project.id === rootkeyRebrand.id && <RootkeyIcons language={language} />}
                    <ImageCarousel
                        images={project.images?.length ? project.images : [project.banner ?? 'favicon.ico']}
                        altPrefix={"Project Image"}
                        className={project.id === rootkeyRebrand.id ? "rootkey-gallery" : undefined}
                        height={project.id === rootkeyRebrand.id ? "min(65vh, 640px)" : undefined}
                        interval={5000}
                    />
                </div>

                {/* Right side - Information */}
                <div className="flex flex-col gap-10 w-full p-6 text-[.7rem] md:w-1/2 md:p-12">

                    <div className="flex flex-row justify-between w-full uppercase">
                        <p className="w-full">
                            {project.projectType.join(", ")}
                        </p>
                        <div className="flex flex-col w-full gap-10">
                            <p>{language === "pt" ? "DATA" : "DATE"}</p>
                            <p>{language === "pt" ? "COM" : "WITH"}</p>
                            <p>TAGS</p>
                            <p>{language === "pt" ? "NOTAS" : "NOTES"}</p>
                            <p>ID</p>
                        </div>
                        <div className="flex flex-col w-full gap-10">
                            <p>{project.date}</p>
                            <p>{project.collaborators.join(", ")}</p>
                            <p>{project.tags.join(", ")}</p>
                            <p>{project.notes}</p>
                            <p>{project.id}</p>
                        </div>
                    </div>

                    {(project.links || project.buyLinks) && <div className="flex flex-col w-full gap-6">
                        {project.links && Object.keys(project.links).length > 0 && <div className="flex flex-row justify-between w-full uppercase">
                            <p className="w-full">
                                {language === "pt" ? "PARTILHAR" : "SHARE"}
                            </p>
                            <div className={`flex flex-col w-full ${project.id === rootkeyRebrand.id ? "pt-10" : ""}`}>
                                {Object.keys(project.links).map((key: string) => (
                                    <a
                                        key={key}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        href={project.links![key]}
                                        className="uppercase cursor-pointer hover:underline"
                                    >
                                        {key}
                                    </a>
                                ))}
                            </div>
                            <div className="w-full"></div>
                        </div>}

                        {project.buyLinks && Object.keys(project.buyLinks).length > 0 && <div className="flex flex-row justify-between w-full uppercase">
                            <div className="w-full"></div>
                            <div className="flex flex-col w-full">
                                {Object.keys(project.buyLinks).map((key: string) => (
                                    <a
                                        key={key}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        href={project.buyLinks![key]}
                                        className="uppercase cursor-pointer hover:underline"
                                    >
                                        {key}
                                    </a>
                                ))}
                            </div>
                            <div className="w-full"></div>
                        </div>}
                    </div>}

                    <div className="flex flex-row justify-between w-full uppercase">
                        <p className="w-full">
                            {language === "pt" ? "NAVEGAÇÃO" : "NAVIGATION"}
                        </p>
                        <div className="flex flex-col items-start w-full text-left">
                            <button className="hover:underline" onClick={prevProject}>PREVIOUS</button>
                            <button className="hover:underline" onClick={nextProject}>NEXT</button>
                        </div>
                        <div className="w-full"></div>
                    </div>

                    <div>
                        <p className="leading-relaxed">{language === "pt" ? project.info_pt : project.info_en}</p>
                    </div>
                </div>
            </div>
        </div>
    )
}
